   !> Nonlocal PCM (gaussian charges): combine and factor the operators for the solvent
   !>
   !> - Repeat with new solvent inputs as often as needed; the cavity operators are reused
   !> - Needs nonlocal_pcm_assemble on the same state first
   !> - Vectors have length npt, matrices are (npt, npt), point fields (3, npt)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of nonlocal_pcm
   !> @param[in] eps  relative permittivity of the solvent (inf for a conductor)
   !> @param[in] eps_inf  high-frequency permittivity of the solvent
   !> @param[in] lam  correlation length of the solvent polarization
   !> @param[in] eps_solute  relative permittivity inside the cavity
   !> @param[out] error  error handling; allocated on failure
   subroutine nonlocal_pcm_mf_medium(state, eps, eps_inf, lam, eps_solute, error)
      !> State of nonlocal_pcm
      type(nonlocal_pcm_state), target, intent(inout) :: state
      !> Relative permittivity of the solvent (inf for a conductor)
      real(wp), intent(in) :: eps
      !> High-frequency permittivity of the solvent
      real(wp), intent(in) :: eps_inf
      !> Correlation length of the solvent polarization
      real(wp), intent(in) :: lam
      !> Relative permittivity inside the cavity
      real(wp), intent(in) :: eps_solute
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt
      integer :: stat
      real(wp) :: tmp1, tmp2, tmp3, tmp4

      stat = 0
      npt = state%npt
      if (state%ready < 1) then
         call fatal_error(error, "[nonlocal_pcm_mf_medium] call nonlocal_pcm_assemble first")
         return
      end if
      state%ready = 1

      state%lam = lam
      state%eps_inf = eps_inf
      state%eps = eps
      state%eps_solute = eps_solute
      state%op2%npt = 3*npt
      state%op2%npoint = npt
      state%op2%id = 2
      state%op2%points => state%r
      state%op2%r => state%r
      state%op2%n => state%n
      state%op2%xi => state%xi
      state%op2%F => state%F
      state%op2%a => state%a
      state%s7 = 1.0_wp/state%lam
      state%s8 = 1.0_wp/state%eps_inf
      state%s9 = state%s8*state%eps
      state%s10 = sqrt(state%s9)
      tmp1 = state%s7*state%s10
      state%s11 = tmp1**(2)
      state%op2%c1 = state%s11
      state%op2%c2 = state%s7
      state%op2%c3 = state%s10
      state%s14 = 1.0_wp/state%eps
      tmp2 = -state%s14
      state%s15 = state%s8 + tmp2
      state%s16 = state%eps_solute*state%s15
      state%op2%c4 = state%s16
      state%s18 = state%s8*state%eps_solute
      state%op2%c5 = state%s18
      state%s20 = state%s14*state%eps_inf
      state%op2%c6 = state%s20
      call state%solver%setup(state%op2, error)
      if (allocated(error)) return
      tmp3 = state%eps_solute*state%s14
      tmp4 = -tmp3
      state%s21 = 1.0_wp + tmp4
      state%s23 = -state%s16
      state%s25 = -state%s18

      state%ready = 2
   end subroutine nonlocal_pcm_mf_medium

