      type(error_type), allocatable, intent(out) :: error

      integer :: npt, nblk, blk

      if (state%ready < 4) then
         call fatal_error(error, "[nonlocal_pcm_mf_tangent] call nonlocal_pcm_weights first")
         return
      end if
      npt = state%npt
      nblk = size(dr, 3)
      if (any(shape(dr) /= [3, npt, nblk])) then
         call fatal_error(error, "[nonlocal_pcm_mf_tangent] dr: wrong shape")
